from pathlib import Path

root=Path('/mnt/data/reliever_work')

# ---------- server.js ----------
p=root/'server.js'
s=p.read_text(encoding='utf-8')
needle="""  db.run(`CREATE TABLE IF NOT EXISTS point_transfer_requests (\n    id INTEGER PRIMARY KEY AUTOINCREMENT, staff_id TEXT NOT NULL, staff_name TEXT NOT NULL, staff_role TEXT NOT NULL,\n    from_location TEXT, to_location TEXT NOT NULL, reason TEXT, status TEXT DEFAULT 'Pending',\n    requested_at TEXT NOT NULL, reviewed_at TEXT, reviewed_by TEXT\n  )`);\n"""
insert=needle+"""  // RELIEVER REQUESTS - Guard/Supervisor can request holiday or medical leave;\n  // Admin/Master Admin approve/reject and select the replacement reliever.\n  db.run(`CREATE TABLE IF NOT EXISTS reliever_requests (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    staff_id TEXT NOT NULL, staff_name TEXT NOT NULL, staff_role TEXT NOT NULL,\n    location_code TEXT NOT NULL, request_type TEXT NOT NULL, reason TEXT NOT NULL,\n    from_date TEXT NOT NULL, to_date TEXT NOT NULL, status TEXT DEFAULT 'Pending',\n    reliever_id TEXT, reliever_name TEXT, reliever_location TEXT,\n    reviewed_at TEXT, reviewed_by TEXT, created_at TEXT NOT NULL\n  )`);\n"""
if needle not in s: raise SystemExit('server schema needle not found')
s=s.replace(needle,insert,1)

needle2="""// TEAM ATTENDANCE - Supervisor sees only guards assigned to them; Field Officer sees assigned supervisors/guards.\n"""
endpoint="""// RELIEVER REQUESTS - Guard/Supervisor request leave/medical relief; Admin/Master Admin review.\napp.get('/api/reliever-requests',auth,(req,res)=>{\n  const isAdmin=['admin','master_admin'].includes(req.user.role);\n  const sql=isAdmin\n    ? `SELECT * FROM reliever_requests ORDER BY CASE status WHEN 'Pending' THEN 0 ELSE 1 END, id DESC LIMIT 300`\n    : `SELECT * FROM reliever_requests WHERE staff_id=? ORDER BY id DESC LIMIT 100`;\n  all(sql,isAdmin?[]:[req.user.staff_id],res);\n});\n\napp.post('/api/reliever-requests',auth,roles('guard','supervisor'),(req,res)=>{\n  const x=req.body||{};\n  const type=String(x.request_type||'').trim();\n  const reason=String(x.reason||'').trim();\n  const from=String(x.from_date||'').trim();\n  const to=String(x.to_date||'').trim();\n  const location=String(req.user.location_code||x.location_code||'').trim();\n  const allowed=['Holiday','Medical / Illness','Emergency'];\n  if(!allowed.includes(type))return res.status(400).json({error:'Select a valid request type'});\n  if(!from||!to||!reason)return res.status(400).json({error:'Request type, dates and reason are required'});\n  if(to<from)return res.status(400).json({error:'To date cannot be before From date'});\n  if(!location)return res.status(400).json({error:'Your Location Code is not assigned'});\n  get(`SELECT id FROM reliever_requests WHERE staff_id=? AND status IN ('Pending','Approved')\n       AND NOT (to_date < ? OR from_date > ?) LIMIT 1`,[req.user.staff_id,from,to],(e,existing)=>{\n    if(e)return res.status(500).json({error:e.message});\n    if(existing)return res.status(409).json({error:'You already have a pending/approved reliever request for these dates'});\n    const now=new Date().toISOString();\n    run(`INSERT INTO reliever_requests(staff_id,staff_name,staff_role,location_code,request_type,reason,from_date,to_date,status,created_at)\n         VALUES(?,?,?,?,?,?,?,?,?,?)`,[req.user.staff_id,req.user.name,req.user.role,location,type,reason,from,to,'Pending',now],res,row=>{\n      audit(req.user,'RELIEVER_REQUEST_CREATED',req.user.staff_id,`${type}; ${from} to ${to}; ${location}`);\n      res.status(201).json({id:row.lastID,message:'Reliever request submitted to Admin'});\n    });\n  });\n});\n\napp.put('/api/reliever-requests/:id/approve',auth,roles('admin','master_admin'),async(req,res)=>{\n  const relieverId=String(req.body?.reliever_id||'').trim();\n  if(!relieverId)return res.status(400).json({error:'Select the Reliever who will cover this duty'});\n  get('SELECT * FROM reliever_requests WHERE id=?',[req.params.id],(e,r)=>{\n    if(e)return res.status(500).json({error:e.message});\n    if(!r)return res.status(404).json({error:'Reliever request not found'});\n    if(r.status!=='Pending')return res.status(409).json({error:'Request already reviewed'});\n    get(`SELECT id,name,staff_id,role,location_code,status,is_reliever,contact_number FROM staff\n         WHERE staff_id=? AND role IN ('officer','supervisor','guard')`,[relieverId],async(re,rel)=>{\n      if(re)return res.status(500).json({error:re.message});\n      if(!rel)return res.status(404).json({error:'Selected Reliever not found'});\n      if(rel.status!=='active')return res.status(400).json({error:'Selected Reliever is not active'});\n      if(!Number(rel.is_reliever))return res.status(400).json({error:'Selected staff is not marked as Reliever in Reliever Management'});\n      if(String(rel.location_code||'')!==String(r.location_code||''))return res.status(400).json({error:`Reliever Location must match request Location ${r.location_code}`});\n      const reviewedAt=new Date().toISOString();\n      run(`UPDATE reliever_requests SET status='Approved',reliever_id=?,reliever_name=?,reliever_location=?,reviewed_at=?,reviewed_by=? WHERE id=?`,\n        [rel.staff_id,rel.name,rel.location_code,reviewedAt,req.user.staff_id,r.id],res,async()=>{\n          const requesterText=`SNDF Reliever Request\n\nHello ${r.staff_name},\nYour ${r.request_type} request has been APPROVED.\n\nLeave: ${r.from_date} to ${r.to_date}\nLocation: ${r.location_code}\nReason: ${r.reason}\n\nReliever: ${rel.name}\nReliever ID: ${rel.staff_id}\nReliever Location: ${rel.location_code}\nApproved by: ${req.user.name||req.user.staff_id}\n\nSNDF Support Services`;\n          const relieverText=`SNDF Reliever Duty\n\nHello ${rel.name},\nYou are assigned as RELIEVER for ${r.staff_name}.\n\nStaff ID: ${r.staff_id}\nLeave: ${r.from_date} to ${r.to_date}\nLocation: ${r.location_code}\nRequest: ${r.request_type}\nReason: ${r.reason}\n\nPlease report to the location and complete attendance as required.\n\nSNDF Support Services`;\n          const [waRequester,waReliever]=await Promise.all([sendWhatsAppMessage((await new Promise(resolve=>get('SELECT contact_number FROM staff WHERE staff_id=?',[r.staff_id],(ee,rr)=>resolve(rr?.contact_number||''))))),requesterText),sendWhatsAppMessage(rel.contact_number,relieverText)]);\n          // In-app notifications work even when WhatsApp Cloud API is not configured.\n          db.run(`INSERT INTO notifications(staff_id,title,message,type,created_at) VALUES(?,?,?,?,?)`,[r.staff_id,'Reliever Request Approved',requesterText,'reliever',reviewedAt]);\n          db.run(`INSERT INTO notifications(staff_id,title,message,type,created_at) VALUES(?,?,?,?,?)`,[rel.staff_id,'Reliever Duty Assigned',relieverText,'reliever',reviewedAt]);\n          audit(req.user,'RELIEVER_REQUEST_APPROVED',r.staff_id,`reliever=${rel.staff_id}; location=${r.location_code}; whatsapp=${waRequester.sent&&waReliever.sent?'both-sent':'not-both'}`);\n          res.json({message:'Request approved and Reliever assigned',reliever:{id:rel.staff_id,name:rel.name,location:rel.location_code},whatsapp_requester:waRequester.sent,whatsapp_reliever:waReliever.sent});\n        });\n    });\n  });\n});\n\napp.put('/api/reliever-requests/:id/reject',auth,roles('admin','master_admin'),(req,res)=>{\n  const reason=String(req.body?.reason||'').trim();\n  get('SELECT * FROM reliever_requests WHERE id=?',[req.params.id],(e,r)=>{\n    if(e)return res.status(500).json({error:e.message});\n    if(!r)return res.status(404).json({error:'Reliever request not found'});\n    if(r.status!=='Pending')return res.status(409).json({error:'Request already reviewed'});\n    const reviewedAt=new Date().toISOString();\n    run(`UPDATE reliever_requests SET status='Rejected',reviewed_at=?,reviewed_by=? WHERE id=?`,[reviewedAt,req.user.staff_id,r.id],res,async()=>{\n      const text=`SNDF Reliever Request\\n\\nHello ${r.staff_name},\\nYour ${r.request_type} request for ${r.from_date} to ${r.to_date} has been REJECTED.\\n\\nLocation: ${r.location_code}\\nReason: ${r.reason}${reason?`\\nAdmin Note: ${reason}`:''}\\n\\nSNDF Support Services`;\n      const target=await new Promise(resolve=>get('SELECT contact_number FROM staff WHERE staff_id=?',[r.staff_id],(ee,rr)=>resolve(rr?.contact_number||'')));\n      const wa=await sendWhatsAppMessage(target,text);\n      db.run(`INSERT INTO notifications(staff_id,title,message,type,created_at) VALUES(?,?,?,?,?)`,[r.staff_id,'Reliever Request Rejected',text,'reliever',reviewedAt]);\n      audit(req.user,'RELIEVER_REQUEST_REJECTED',r.staff_id,reason||'No admin note');\n      res.json({message:'Reliever request rejected',whatsapp_sent:wa.sent});\n    });\n  });\n});\n\n"""
if needle2 not in s: raise SystemExit('team attendance needle not found')
s=s.replace(needle2,endpoint+needle2,1)
p.write_text(s,encoding='utf-8')

# ---------- app.js ----------
p=root/'app.js'
s=p.read_text(encoding='utf-8')
# Refresh: load requests after relievers for admin, and for guard/supervisor.
old="""if(role==='field_officer'){const x=$('#createOfficerParent');if(x)x.value=user.staff_id;const l=$('#createOfficerLocation');if(l)l.value=user.location_code||'';const b=$('#myOfficerRows');if(b)b.innerHTML=staff.filter(x=>x.role==='officer'&&x.parent_id===user.staff_id).map(x=>`<tr><td>${escape(x.name)}</td><td>${escape(x.staff_id)}</td><td>${escape(x.location_code||'—')}</td><td>${escape(x.status||'active')}</td></tr>`).join('')||'<tr><td colspan=4>No Officers found.</td></tr>';}\nwindow._attendanceRows=a;renderStaff(s);renderProfileRecords(s);fillCreateParent(s);renderAttendance(a);renderFines(f);renderAccount(ac);$$('[data-stat]').forEach(x=>x.textContent=stats[x.dataset.stat]??0);fillTargets(s);fillAdvanceTargets(s);renderDaily(a);loadNotices();loadHelp();loadPointTransfers();loadTaskTargets();loadTasks();if(!isAdminRole)loadTransferPoints();if(isAdminRole){loadPayroll();loadReports();loadRelievers();loadPointUpdates();loadDirectTransferPoints();}if(['supervisor','officer','field_officer'].includes(role))loadTeamAttendance();}catch(e){console.log(e.message)}}\n"""
new="""if(role==='field_officer'){const x=$('#createOfficerParent');if(x)x.value=user.staff_id;const l=$('#createOfficerLocation');if(l)l.value=user.location_code||'';const b=$('#myOfficerRows');if(b)b.innerHTML=staff.filter(x=>x.role==='officer'&&x.parent_id===user.staff_id).map(x=>`<tr><td>${escape(x.name)}</td><td>${escape(x.staff_id)}</td><td>${escape(x.location_code||'—')}</td><td>${escape(x.status||'active')}</td></tr>`).join('')||'<tr><td colspan=4>No Officers found.</td></tr>';}\nwindow._attendanceRows=a;renderStaff(s);renderProfileRecords(s);fillCreateParent(s);renderAttendance(a);renderFines(f);renderAccount(ac);$$('[data-stat]').forEach(x=>x.textContent=stats[x.dataset.stat]??0);fillTargets(s);fillAdvanceTargets(s);renderDaily(a);loadNotices();loadHelp();loadPointTransfers();loadTaskTargets();loadTasks();loadRelieverRequests();if(!isAdminRole)loadTransferPoints();if(isAdminRole){loadPayroll();loadReports();loadRelievers();loadPointUpdates();loadDirectTransferPoints();}if(['supervisor','officer','field_officer'].includes(role))loadTeamAttendance();}catch(e){console.log(e.message)}}\n"""
if old not in s: raise SystemExit('refresh block not found')
s=s.replace(old,new,1)
# Insert functions before loadRelievers
needle="""// =====================================================\n\n// SECTION: FUNCTION loadRelievers\n"""
block="""// =====================================================\n// SECTION: RELIEVER REQUEST MANAGEMENT\n// =====================================================\nasync function loadRelieverRequests(){\n  const table=$('#relieverRequestRows'), mine=$('#myRelieverRequestRows');\n  if(!table&&!mine)return;\n  try{\n    const rows=await api('/reliever-requests');\n    if(table){\n      const relievers=(window._relievers||[]).filter(x=>x.status==='active'&&Number(x.is_reliever)===1);\n      table.innerHTML=rows.map(x=>{\n        const options=relievers.filter(r=>String(r.location_code||'')===String(x.location_code||'')).map(r=>`<option value=\"${escape(r.staff_id)}\">${escape(r.name)} — ${escape(r.staff_id)} — ${escape(r.location_code||'')}</option>`).join('');\n        const action=x.status==='Pending' ? `<select id=\"requestReliever_${x.id}\"><option value=\"\">Select Reliever</option>${options}</select> <button class=\"action success\" onclick=\"approveRelieverRequest(${x.id})\">✓ Approve</button> <button class=\"action danger\" onclick=\"rejectRelieverRequest(${x.id})\">✕ Reject</button>` : '—';\n        const assigned=x.reliever_id?`${escape(x.reliever_name)} (${escape(x.reliever_id)})<br><small>${escape(x.reliever_location||'—')}</small>`:'—';\n        return `<tr><td>${escape(label(x.staff_role))}</td><td>${escape(x.staff_name)}</td><td>${escape(x.staff_id)}</td><td>${escape(x.location_code)}</td><td>${escape(x.request_type)}</td><td>${escape(x.from_date)} → ${escape(x.to_date)}</td><td>${escape(x.reason)}</td><td><b>${escape(x.status)}</b></td><td>${assigned}</td><td>${action}</td></tr>`;\n      }).join('')||'<tr><td colspan=10>No reliever requests.</td></tr>';\n    }\n    if(mine){\n      mine.innerHTML=rows.map(x=>{const assigned=x.reliever_id?`${escape(x.reliever_name)} (${escape(x.reliever_id)}) • ${escape(x.reliever_location||'—')}`:'Not assigned yet';return `<div class=\"panel reliever-request-card\"><div><b>${escape(x.request_type)}</b> <span class=\"request-status\">${escape(x.status)}</span></div><p><b>${escape(x.from_date)} → ${escape(x.to_date)}</b> • Location: <b>${escape(x.location_code)}</b></p><p>${escape(x.reason)}</p><p>Reliever: <b>${assigned}</b></p><small>${escape(x.created_at||'')}</small></div>`;}).join('')||'<p class=\"muted-note\">No requests submitted yet.</p>';\n    }\n  }catch(e){console.log('Reliever requests:',e.message)}\n}\n\nasync function approveRelieverRequest(id){\n  const sel=$('#requestReliever_'+id);\n  const reliever_id=sel?.value||'';\n  if(!reliever_id)return alert('Select the Reliever who will cover this duty.');\n  if(!confirm('Approve this leave request and assign the selected Reliever?'))return;\n  try{const r=await api('/reliever-requests/'+id+'/approve',{method:'PUT',body:JSON.stringify({reliever_id})});msg(r.message||'Request approved ✓');loadRelieverRequests();loadRelievers();}catch(e){alert(e.message)}\n}\nasync function rejectRelieverRequest(id){\n  const reason=prompt('Optional rejection note:','');\n  if(reason===null)return;\n  if(!confirm('Reject this reliever request?'))return;\n  try{const r=await api('/reliever-requests/'+id+'/reject',{method:'PUT',body:JSON.stringify({reason})});msg(r.message||'Request rejected');loadRelieverRequests();}catch(e){alert(e.message)}\n}\nwindow.approveRelieverRequest=approveRelieverRequest;window.rejectRelieverRequest=rejectRelieverRequest;\n\n$('#relieverRequestForm')?.addEventListener('submit',async e=>{\n  e.preventDefault();\n  const d=Object.fromEntries(new FormData(e.target));\n  try{const r=await api('/reliever-requests',{method:'POST',body:JSON.stringify(d)});msg(r.message||'Request submitted ✓');e.target.reset();$('#requestName')&&( $('#requestName').value=user.name||'');$('#requestStaffId')&&( $('#requestStaffId').value=user.staff_id||'');$('#requestLocation')&&( $('#requestLocation').value=user.location_code||'');loadRelieverRequests();}catch(err){alert(err.message)}\n});\n\n"""+needle
if needle not in s: raise SystemExit('loadRelievers marker not found')
s=s.replace(needle,block,1)
# Make loadRelievers trigger request render after it has loaded, useful for admin.
s=s.replace("""    if(unselectedBox)unselectedBox.innerHTML=active.filter(x=>Number(x.is_reliever)!==1).map(rowMini).join('')||'<tr><td colspan=\"4\">No unselected members.</td></tr>';\n  }catch(e){console.log(e.message)}\n}""","""    if(unselectedBox)unselectedBox.innerHTML=active.filter(x=>Number(x.is_reliever)!==1).map(rowMini).join('')||'<tr><td colspan=\"4\">No unselected members.</td></tr>';\n    loadRelieverRequests();\n  }catch(e){console.log(e.message)}\n}""",1)
p.write_text(s,encoding='utf-8')

